// gen/ 注册总入口(schema_dumper --gen 生成的三个注册器聚合)
// The aggregate entry of the gen/ registration (assembling the three
// registrars generated by schema_dumper --gen).
import std;
#include "meta/field_loader.hpp"
#include "meta/parse.hpp"
#include "meta/generic_record.hpp"

namespace ora::gen {

void RegisterGeneratedEnums();
void RegisterGeneratedBitSets();
void RegisterGeneratedTypes();

/// 一次性装载全部生成注册表(枚举/BitSet 标签/类型工厂);
/// 引擎与测试的加载链入口各调用一次(重复调用幂等:insert_or_assign)
/// Load every generated registry in one go (enums/BitSet tags/type
/// factories); each loading-chain entry (engine or tests) calls this once
/// (idempotent via insert_or_assign).
void RegisterGeneratedAll() {
  RegisterGeneratedEnums();
  RegisterGeneratedBitSets();
  RegisterGeneratedTypes();
}

}  // namespace ora::gen
